from solution import iscube
import time

import pytest
from hypothesis import given, strategies as st


# ---- obviously-correct reference model (integer binary search) ----
def ref_iscube(a: int) -> bool:
    if a == 0:
        return True
    neg = a < 0
    m = -a if neg else a
    lo, hi = 1, m
    # tighten upper bound: hi = min(m, int(m**(1/3))+2) not needed; binary search is fine for small m
    while lo <= hi:
        mid = (lo + hi) // 2
        c = mid * mid * mid
        if c == m:
            return True
        if c < m:
            lo = mid + 1
        else:
            hi = mid - 1
    return False


# ---- concrete examples from the spec ----
@pytest.mark.parametrize(
    "a, expected",
    [
        (1, True),
        (2, False),
        (-1, True),
        (64, True),
        (0, True),
        (180, False),
    ],
)
def test_spec_examples(a, expected):
    result = iscube(a)
    assert result is expected


def test_spec_zero_is_true():
    assert iscube(0) is True


def test_returns_bool_type():
    for a in [0, 1, 2, -1, 64, 180, 8, -8, 27, -27, 9]:
        r = iscube(a)
        assert type(r) is bool


# ---- properties ----

@given(st.integers(min_value=-50, max_value=50))
def test_property_cubes_of_integers_are_true(n):
    assert iscube(n ** 3) is True


@given(st.integers(min_value=-500, max_value=500))
def test_property_agrees_with_reference_model(a):
    assert iscube(a) is ref_iscube(a)


@given(st.integers(min_value=-50, max_value=50))
def test_property_sign_symmetry(a):
    # a is a cube iff -a is a cube, since (-k)^3 == -(k^3)
    assert iscube(a) is iscube(-a)


@given(st.integers(min_value=0, max_value=30))
def test_property_gap_between_consecutive_cubes_has_no_cube(n):
    lo = n ** 3
    hi = (n + 1) ** 3
    for a in range(lo + 1, hi):
        assert iscube(a) is False


@given(st.integers(min_value=-30, max_value=-1))
def test_property_gap_between_consecutive_negative_cubes(n):
    # n negative: n^3 < (n+1)^3, gap contains no cubes
    lo = n ** 3
    hi = (n + 1) ** 3
    for a in range(lo + 1, hi):
        assert iscube(a) is False


@given(st.integers(min_value=0, max_value=30))
def test_property_non_cube_neighbors_of_cubes(n):
    c = n ** 3
    if c + 1 != (n + 1) ** 3:
        assert iscube(c + 1) is False
    if c - 1 != (n - 1) ** 3 and c - 1 >= 0:
        # c-1 could itself be a cube only in tiny cases; check via reference
        assert iscube(c - 1) is ref_iscube(c - 1)


def test_property_small_perfect_cubes():
    for k in range(-10, 11):
        assert iscube(k ** 3) is True


def test_property_small_non_cubes_exhaustive():
    cubes = {k ** 3 for k in range(-10, 11)}
    for a in range(-1000, 1001):
        assert iscube(a) is (a in cubes)


def test_property_180_neighbors():
    assert iscube(125) is True
    assert iscube(126) is False
    assert iscube(216) is True
    assert iscube(180) is False


def test_property_negative_cubes():
    assert iscube(-8) is True
    assert iscube(-27) is True
    assert iscube(-64) is True
    assert iscube(-9) is False
    assert iscube(-100) is False


def test_property_large_cube_still_true():
    # perfect cubes must be recognised even when large;
    # a correct implementation is O(log a), so this is instant.
    assert iscube(1000 ** 3) is True
    assert iscube(-(1000 ** 3)) is True
    assert iscube(10 ** 18) is True  # (10**6)**3


def test_property_large_non_cube_efficient():
    # 1000001 is not a cube (100^3 == 1000000, 101^3 == 1030301).
    # A linear scan up to `a` is far too slow; a correct
    # implementation answers essentially instantly.
    a = 1_000_001
    assert ref_iscube(a) is False
    start = time.perf_counter()
    result = iscube(a)
    elapsed = time.perf_counter() - start
    assert result is False
    assert elapsed < 0.05, f"iscube({a}) took {elapsed:.3f}s, too slow"
